def is_hill_number(n):
    s = str(n)
    peak_found = False
    for i in range(1, len(s)):
        if s[i] > s[i - 1]:
            if peak_found:
                return False
        elif s[i] < s[i - 1]:
            peak_found = True
    return peak_found

def count_hill_numbers(n):
    s = str(n)
    length = len(s)

    # Count all numbers with fewer digits
    count = sum(9 * 10**(i - 1) for i in range(1, length))

    # Count numbers with the same number of digits
    for i in range(1, length):
        # Choose the first digit (1-9)
        count += 9 * 10**(i - 1)

    # Count valid numbers starting with the first digit of n
    first_digit = int(s[0])
    for i in range(1, first_digit):
        count += 10**(length - 1)

    # Check if n itself is a hill number
    if is_hill_number(n):
        count += 1

    return count

